-- PT120-S4-Q3. Batch 08.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch08$PT120-S4-Q3$batch08$ AND q.stimulus=$batch08$Professor: The best users of a language are its great authors. However, these authors often use language in ways that are innovative and idiosyncratic, and are therefore less respectful of the strictures of proper usage than most of us are.$batch08$ AND q.prompt=$batch08$The Professor's statements, if true, most support which one of the following?$batch08$ AND q.correct_choice=$batch08$C$batch08$) THEN RAISE EXCEPTION 'Question changed: PT120-S4-Q3'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch08$PT120-S4-Q3$batch08$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT120-S4-Q3'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch08$PT120-S4-Q3$batch08$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch08$Statements$batch08$, $batch08$The best users of a language are its great authors. But great authors use language innovatively and idiosyncratically, so they respect proper usage less than most of us do.$batch08$), (1, $batch08$Evaluate$batch08$, $batch08$Pause and infer by joining the two sentences. The best users of the language are the great authors, and the great authors observe proper usage less than most people. So the best users observe proper usage less than most people.$batch08$), (2, $batch08$Goal$batch08$, $batch08$The most skilled users of a language follow proper usage less than most people.$batch08$)) v(position,label,body) WHERE q.qid=$batch08$PT120-S4-Q3$batch08$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch08$A$batch08$, $batch08$The passage gives no advice to aspiring writers.$batch08$), ($batch08$B$batch08$, $batch08$This is the most popular wrong answer. The passage goes from idiosyncratic style to ignoring proper usage. B runs it backward: ignoring proper usage leads to an idiosyncratic style. And "risk" adds a danger the passage never mentions.$batch08$), ($batch08$C$batch08$, $batch08$Best users = great authors, and great authors are less respectful of proper usage than most. C joins the two.$batch08$), ($batch08$D$batch08$, $batch08$Nobody's criticism comes up.$batch08$), ($batch08$E$batch08$, $batch08$The passage doesn't say who should set the standard.$batch08$)) v(letter,body) WHERE q.qid=$batch08$PT120-S4-Q3$batch08$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
